function validate([nums, target]) {
  if (nums.length > 3500) return 'nums has at most 3500 values.';
  if (nums.some(v => v < -100 || v > 100)) return 'Each value is between -100 and 100.';
  if (target < -100 || target > 100) return 'target is between -100 and 100.';
  return null;
}

