function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  if (size === 'large') {
    const nums = Array.from({ length: 2000 }, () => pick(201) - 100);
    return [nums, pick(201) - 100];
  }
  const span = rand() < 0.6 ? 5 : 100;
  const n = pick(9);
  const nums = Array.from({ length: n }, () => pick(2 * span + 1) - span);
  const reach = Math.min(100, 3 * span);
  return [nums, pick(2 * reach + 1) - reach];
}
